drop policy if exists categories_manage_manager on public.categories;
create policy categories_insert_manager on public.categories for insert to authenticated with check (exists(select 1 from public.branch_memberships m where m.branch_id=categories.branch_id and m.user_id=(select auth.uid()) and m.role in ('admin','manager')));
create policy categories_update_manager on public.categories for update to authenticated using (exists(select 1 from public.branch_memberships m where m.branch_id=categories.branch_id and m.user_id=(select auth.uid()) and m.role in ('admin','manager'))) with check (exists(select 1 from public.branch_memberships m where m.branch_id=categories.branch_id and m.user_id=(select auth.uid()) and m.role in ('admin','manager')));
create policy categories_delete_manager on public.categories for delete to authenticated using (exists(select 1 from public.branch_memberships m where m.branch_id=categories.branch_id and m.user_id=(select auth.uid()) and m.role in ('admin','manager')));
drop policy if exists products_manage_manager on public.products;
create policy products_insert_manager on public.products for insert to authenticated with check (exists(select 1 from public.branch_memberships m where m.branch_id=products.branch_id and m.user_id=(select auth.uid()) and m.role in ('admin','manager')));
create policy products_update_manager on public.products for update to authenticated using (exists(select 1 from public.branch_memberships m where m.branch_id=products.branch_id and m.user_id=(select auth.uid()) and m.role in ('admin','manager'))) with check (exists(select 1 from public.branch_memberships m where m.branch_id=products.branch_id and m.user_id=(select auth.uid()) and m.role in ('admin','manager')));
create policy products_delete_manager on public.products for delete to authenticated using (exists(select 1 from public.branch_memberships m where m.branch_id=products.branch_id and m.user_id=(select auth.uid()) and m.role in ('admin','manager')));
drop policy if exists jobs_manage_manager on public.employee_jobs;
create policy jobs_insert_manager on public.employee_jobs for insert to authenticated with check (created_by=(select auth.uid()) and exists(select 1 from public.branch_memberships m where m.branch_id=employee_jobs.branch_id and m.user_id=(select auth.uid()) and m.role in ('admin','manager')));
create policy jobs_update_manager on public.employee_jobs for update to authenticated using (exists(select 1 from public.branch_memberships m where m.branch_id=employee_jobs.branch_id and m.user_id=(select auth.uid()) and m.role in ('admin','manager'))) with check (created_by=(select auth.uid()) and exists(select 1 from public.branch_memberships m where m.branch_id=employee_jobs.branch_id and m.user_id=(select auth.uid()) and m.role in ('admin','manager')));
create policy jobs_delete_manager on public.employee_jobs for delete to authenticated using (exists(select 1 from public.branch_memberships m where m.branch_id=employee_jobs.branch_id and m.user_id=(select auth.uid()) and m.role in ('admin','manager')));
